using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Globalization;
using System.Text.RegularExpressions;
namespace Ara {
 public static class NotionDaily {
  public delegate Dictionary<string,object> Call(string suffix,Dictionary<string,object> args);
  static Exception Fail(string s){return new InvalidDataException(s);}
  static string S(Dictionary<string,object> d,string k){return JsonMap.Str(d,k);}
  public static Dictionary<string,object> Decode(Dictionary<string,object> result){if(S(result,"isError")=="True")throw Fail("노션 작업 실패: "+JsonMap.Write(result));if(result.ContainsKey("structuredContent"))return JsonMap.Child(result,"structuredContent");if(!result.ContainsKey("content"))return result;string raw=string.Concat(JsonMap.Items(result,"content").Select(x=>JsonMap.Map(x)).Where(x=>S(x,"type")=="text").Select(x=>S(x,"text")));if(raw.TrimStart().StartsWith("{"))return JsonMap.Read(raw);if(raw.TrimStart().StartsWith("["))return JsonMap.Obj("results",JsonMap.Codec().DeserializeObject(raw));return JsonMap.Obj("text",raw);}
  public static string Date(Dictionary<string,object> input){string d=S(input,"date");DateTime value;if(!DateTime.TryParseExact(d,"yyyy-MM-dd",CultureInfo.InvariantCulture,DateTimeStyles.None,out value))throw Fail("기상한 날짜를 확인해 주세요.");return d;}
  public static string Id(string raw){var m=Regex.Match(raw,@"(?i)([a-f0-9]{8}-?[a-f0-9]{4}-?[a-f0-9]{4}-?[a-f0-9]{4}-?[a-f0-9]{12})(?:[/?].*)?$");Guid id;if(!m.Success||!Guid.TryParse(m.Groups[1].Value,out id))throw Fail("노션 ID를 확인해 주세요.");return id.ToString();}
  public static string Source(Dictionary<string,object> target,Call call){if(target.Count==0)throw Fail("저장할 하루 기록 데이터베이스를 먼저 지정해 주세요.");string targetId=Id(S(target,"id"));var fetched=Decode(call("fetch",JsonMap.Obj("id",S(target,"kind")=="data_source"?"collection://"+targetId:targetId)));string text=S(fetched,"text");if(text.Length==0)text=JsonMap.Write(fetched);var sources=Regex.Matches(text,@"collection://([a-fA-F0-9-]{32,36})").Cast<Match>().Select(x=>Id(x.Groups[1].Value)).Distinct().ToArray();string src=S(target,"kind")=="data_source"?targetId:sources.Length==1?sources[0]:"";if(src.Length==0||!sources.Contains(src))throw Fail("데이터 원본을 하나로 지정해 주세요.");foreach(string key in new[]{"제목","date:날짜:start","집중도","만족도","집중 총점","기록 시간(분)"})if(!text.Contains("\""+key+"\""))throw Fail("하루 기록 DB의 필수 속성이 없습니다: "+key);return src;}
  static double Num(Dictionary<string,object> input,string key,double min,double max){object v;if(!input.TryGetValue(key,out v)||v is string||v is bool||v==null)throw Fail("기록 요약 숫자를 확인해 주세요.");double n=Convert.ToDouble(v,CultureInfo.InvariantCulture);if(double.IsNaN(n)||double.IsInfinity(n)||n<min||n>max)throw Fail("기록 요약 범위를 확인해 주세요.");return n;}
  public static Dictionary<string,object> Properties(Dictionary<string,object> input){string date=Date(input);double minutes=Num(input,"minutes",0,2880),total=Num(input,"focusTotal",0,1440),focus=Num(input,"focusAverage",0,5),sat=Num(input,"satisfactionAverage",0,5);if(minutes%10!=0||total%1!=0||total>minutes/10*5||Math.Abs(focus-(minutes==0?0:total/(minutes/10)))>.011)throw Fail("하루 점수와 기록 시간을 확인해 주세요.");return JsonMap.Obj("date:날짜:start",date,"date:날짜:is_datetime",0,"집중도",focus,"만족도",sat,"집중 총점",total,"기록 시간(분)",minutes);}
  public static object[] Rows(Dictionary<string,object> result){foreach(string key in new[]{"results","rows","data"}){object v;if(!result.TryGetValue(key,out v))continue;if(v is object[]||v is System.Collections.ArrayList)return JsonMap.Items(result,key);var o=JsonMap.Map(v);foreach(string nested in new[]{"results","rows"})if(o.ContainsKey(nested))return JsonMap.Items(o,nested);}throw Fail("기존 날짜 기록 조회 결과를 확인하지 못했습니다. 새 행을 만들지 않았습니다.");}
  public static Dictionary<string,object> Save(Dictionary<string,object> input,Dictionary<string,object> target,bool pending,Call call,Action<bool> mark){var props=Properties(input);string date=Date(input),src=Source(target,call),uri="collection://"+src;var data=JsonMap.Obj("mode","sql","data_source_urls",new[]{uri},"query","SELECT * FROM \""+uri+"\" WHERE \"date:날짜:start\" = ? LIMIT 2","params",new[]{date});var rows=Rows(Decode(call("query-data-sources",JsonMap.Obj("data",data))));if(rows.Length>1)throw Fail("같은 기상일의 행이 여러 개 있습니다. 노션에서 중복을 정리한 뒤 다시 저장해 주세요.");bool created=rows.Length==0;string pageId;
   if(!created){var row=JsonMap.Map(rows[0]);pageId=Id(S(row,"url").Length>0?S(row,"url"):S(row,"id"));Decode(call("update-page",JsonMap.Obj("page_id",pageId,"command","update_properties","allow_async",false,"properties",props)));mark(false);NotionDiary.Update(pageId,input,call);}
   else{if(pending)throw Fail("이 날짜의 생성 결과를 확인 중입니다. 노션에서 행 유무를 확인해 주세요. 중복 생성을 막았습니다.");mark(true);props["제목"]=date+" 하루 기록";var result=Decode(call("create-pages",JsonMap.Obj("parent",JsonMap.Obj("data_source_id",src),"allow_async",false,"pages",new[]{NotionDiary.NewPage(props,input)})));var pages=JsonMap.Items(result,"pages");if(pages.Length==0)pages=JsonMap.Items(result,"results");var row=pages.Length>0?JsonMap.Map(pages[0]):result;try{pageId=Id(S(row,"url").Length>0?S(row,"url"):S(row,"id"));}catch{throw Fail("행은 생성됐을 수 있습니다. 다시 저장하면 기존 날짜를 먼저 조회합니다.");}mark(false);NotionDiary.Update(pageId,input,call);}
   return JsonMap.Obj("saved",true,"created",created,"date",date,"url","https://www.notion.so/"+pageId.Replace("-",""));
  }
  public static Dictionary<string,object> Inline(Dictionary<string,object> target,Call call,Action<bool> mark){string parent=Id(S(target,"parentId")),src=Source(target,call);var page=Decode(call("fetch",JsonMap.Obj("id",parent)));string text=S(page,"text"),body=Regex.Replace(Regex.Replace(text,@"(?s)^.*?<content>",""),@"(?s)</content>.*$","");if(Regex.Matches(body,@"<database\b[^>]*>").Cast<Match>().Any(m=>m.Value.Contains("inline=\"true\"")&&(m.Value.Contains(src)||m.Value.Contains(src.Replace("-","")))))return JsonMap.Obj("saved",true,"existing",true);if(S(target,"inlinePending")=="True")throw Fail("페이지 표 생성 결과가 불확실합니다. 노션 페이지를 먼저 확인해 주세요.");mark(true);Decode(call("create-view",JsonMap.Obj("parent_page_id",parent,"data_source_id",src,"name","날짜별 기록","type","table","configure","SHOW \"날짜\", \"제목\", \"집중도\", \"만족도\", \"집중 총점\", \"기록 시간(분)\"; SORT BY \"날짜\" DESC")));mark(false);return JsonMap.Obj("saved",true);}
 }
}
